import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { spawn } from 'node:child_process';

const serverUrl = 'http://localhost:8888';
let server;

async function waitForServer(process) {
  const deadline = Date.now() + 10000;

  while (Date.now() < deadline) {
    if (process.exitCode !== null) {
      throw new Error(`Server exited with code ${process.exitCode}`);
    }

    try {
      await fetch(serverUrl);
      return;
    } catch {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }

  throw new Error('Server did not start within 10 seconds');
}

describe('HTTP routes', () => {
  beforeAll(async () => {
    server = spawn(process.execPath, ['index.js'], { stdio: 'ignore' });
    await waitForServer(server);
  });

  afterAll(() => {
    if (server && server.exitCode === null) {
      server.kill();
    }
  });

  it('serves the home page with a link to the about page', async () => {
    const response = await fetch(serverUrl);
    const body = await response.text();

    expect(response.status).toBe(200);
    expect(body).toContain('อัปเกรดโลกของคุณ');
    expect(body).toContain('href="/about">เกี่ยวกับเรา</a>');
  });

  it('serves the about page with links back to the home page', async () => {
    const response = await fetch(`${serverUrl}/about`);
    const body = await response.text();

    expect(response.status).toBe(200);
    expect(body).toContain('รู้จัก SAPPHIRETECH');
    expect(body).toContain('href="/">หน้าหลัก</a>');
    expect(body).toContain('href="/about#contact">ติดต่อเรา</a>');
  });
});
